CREATE OR REPLACE FUNCTION public.foreign_destination_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.country IS DISTINCT FROM OLD.country AND NEW.country_code IS NOT DISTINCT FROM OLD.country_code THEN NEW.country_code:=public.country_iso(NEW.country); ELSIF TG_OP='INSERT' OR NEW.country_code IS DISTINCT FROM OLD.country_code THEN NEW.country_code:=public.country_iso(COALESCE(NEW.country_code,NEW.country)); END IF; IF NEW.country_code IS NULL THEN NEW.country_provenance:='UNKNOWN'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.foreign_work_verify_rollback() RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
DECLARE uid uuid:=auth.uid(); i uuid; other_i uuid; c uuid; p uuid; p2 uuid; t uuid; e uuid; corrected uuid; fp uuid; fp2 uuid; r uuid; doc uuid; n integer; s text; before_hours numeric; results jsonb:='[]';
BEGIN
 IF uid IS NULL OR NOT public.has_role(uid,'admin') THEN RAISE EXCEPTION 'Admin only' USING ERRCODE='42501'; END IF;
 SELECT id INTO i FROM public.installers WHERE profile_id=uid AND sandbox LIMIT 1;
 IF i IS NULL THEN RAISE EXCEPTION 'Synthetic installer required'; END IF;
 BEGIN
 INSERT INTO public.clients(name,customer_number,sandbox) VALUES('TEST-FW-ROLLBACK','TEST-FW-ROLLBACK',true) RETURNING id INTO c;
 INSERT INTO public.projects(name,ref,client_id,project_type,status,start_date,end_date,country,country_code,country_provenance,sandbox) VALUES('TEST-FW-ROLLBACK','TEST-FW-ROLLBACK-'||gen_random_uuid(),'installation'::text::uuid,'installation','open','2026-03-01','2026-03-15','Finland','FI','CONFIRMED',true) RETURNING id INTO p;
 EXCEPTION WHEN invalid_text_representation THEN
 INSERT INTO public.projects(name,ref,client_id,project_type,status,start_date,end_date,country,country_code,country_provenance,sandbox) VALUES('TEST-FW-ROLLBACK','TEST-FW-ROLLBACK-'||gen_random_uuid(),c,'installation','open','2026-03-01','2026-03-15','Finland','FI','CONFIRMED',true) RETURNING id INTO p;
 END;
 BEGIN
 INSERT INTO public.time_entries(project_id,installer_id,entry_date,hours,travel_hours,source,client_id,note) SELECT p,i,d::date,8,0,'manual',c,'TEST-FW-ROLLBACK work' FROM generate_series('2026-03-02'::date,'2026-03-06'::date,'1 day') d;
 SELECT id INTO t FROM public.time_entries WHERE project_id=p ORDER BY entry_date LIMIT 1;
 SELECT verification INTO s FROM public.foreign_work_days('2026-03-02','2026-03-02',i) WHERE country='FI';
 results:=results||jsonb_build_object('id','A03','status',CASE WHEN s='DERIVED' THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','B03','status',CASE WHEN s='DERIVED' THEN 'PASS' ELSE 'FAIL' END);
 UPDATE public.projects SET status='completed' WHERE id=p;
 SELECT verification INTO s FROM public.foreign_work_days('2026-03-02','2026-03-02',i) WHERE country='FI';
 results:=results||jsonb_build_object('id','A01','status',CASE WHEN s='VERIFIED' THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','A02','status',CASE WHEN s='VERIFIED' AND (SELECT status FROM public.projects WHERE id=p)='completed' THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','A05','status',CASE WHEN EXISTS(SELECT 1 FROM public.project_status_events WHERE project_id=p AND to_status='completed') THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','D01','status',CASE WHEN (SELECT country_provenance FROM public.projects WHERE id=p)='CONFIRMED' THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','E01','status',CASE WHEN (SELECT count(*) FROM public.foreign_work_days('2026-03-01','2026-03-06',i) WHERE is_work AND country='FI')=5 THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','E05','status',CASE WHEN NOT EXISTS(SELECT 1 FROM public.foreign_work_days('2026-03-01','2026-03-06',i) WHERE presence_source='presence_period') THEN 'PASS' ELSE 'FAIL' END);
 SELECT sum(hours+travel_hours) INTO before_hours FROM public.time_entries WHERE installer_id=i;
 PERFORM public.set_installer_home_country(i,'FI');
 results:=results||jsonb_build_object('id','B01','status',CASE WHEN (SELECT count(*) FROM public.foreign_work_days('2026-03-01','2026-03-06',i) WHERE is_work AND country='FI')=5 THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','I02','status',CASE WHEN EXISTS(SELECT 1 FROM public.audit_log WHERE entity_id=i::text AND entity_type='installer_home_country' AND old_values->>'home_country'='SE' AND new_values->>'home_country'='FI') THEN 'PASS' ELSE 'FAIL' END);
 PERFORM public.set_installer_home_country(i,'SE');
 UPDATE public.projects SET country='Norge' WHERE id=p;
 results:=results||jsonb_build_object('id','B02','status',CASE WHEN (SELECT count(*) FROM public.foreign_work_days('2026-03-01','2026-03-06',i) WHERE is_work AND country='FI')=5 THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','I01','status',CASE WHEN EXISTS(SELECT 1 FROM public.audit_log WHERE entity_id=p::text AND entity_type='foreign_project_country' AND old_values->>'country'='Finland' AND new_values->>'country'='Norge') THEN 'PASS' ELSE 'FAIL' END);
 SELECT id INTO e FROM public.foreign_work_country_evidence WHERE time_entry_id=t AND voided_at IS NULL;
 corrected:=public.correct_foreign_country_evidence(e,'NO','SE','TEST-FW approved single-evidence correction');
 results:=results||jsonb_build_object('id','B04','status',CASE WHEN (SELECT count(*) FROM public.foreign_work_days('2026-03-01','2026-03-06',i) WHERE is_work AND country='FI')=4 AND (SELECT count(*) FROM public.foreign_work_days('2026-03-01','2026-03-06',i) WHERE is_work AND country='NO')=1 THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','B05','status',CASE WHEN EXISTS(SELECT 1 FROM public.audit_log WHERE entity_id=corrected::text AND new_values->>'corrects_id'=e::text) THEN 'PASS' ELSE 'FAIL' END);
 PERFORM public.correct_foreign_country_evidence(corrected,'FI','SE','TEST-FW restore synthetic country');
 results:=results||jsonb_build_object('id','F05','status',CASE WHEN before_hours=(SELECT sum(hours+travel_hours) FROM public.time_entries WHERE installer_id=i) THEN 'PASS' ELSE 'FAIL' END);
 UPDATE public.time_entries SET hours=0 WHERE id=t;
 results:=results||jsonb_build_object('id','F04','status',CASE WHEN (SELECT count(*) FROM public.foreign_work_days('2026-03-01','2026-03-06',i) WHERE is_work AND country='FI')=4 THEN 'PASS' ELSE 'FAIL' END);
 UPDATE public.time_entries SET hours=8 WHERE id=t;
 INSERT INTO public.foreign_work_periods(installer_id,project_id,country,start_at,end_at,kind,verification_status,notes) VALUES(i,p,'FI','2026-03-01 18:00+01','2026-03-06 20:00+01','presence','MANUALLY_CONFIRMED','TEST-FW explicit presence') RETURNING id INTO fp;
 results:=results||jsonb_build_object('id','E04','status',CASE WHEN (SELECT count(*) FILTER(WHERE is_work)=5 AND count(*) FILTER(WHERE presence_source='presence_period')=6 FROM public.foreign_work_days('2026-03-01','2026-03-06',i) WHERE country='FI') THEN 'PASS' ELSE 'FAIL' END);
 INSERT INTO public.foreign_work_periods(installer_id,country,start_at,end_at,kind,verification_status) VALUES(i,'FI','2026-03-02 10:00+01','2026-03-05 20:00+01','presence','MANUALLY_CONFIRMED');
 results:=results||jsonb_build_object('id','E06','status',CASE WHEN (SELECT count(*) FROM public.foreign_work_days('2026-03-01','2026-03-06',i) WHERE country='FI')=6 THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','E07','status',CASE WHEN (SELECT count(*)=count(DISTINCT (installer_id,country,day)) FROM public.foreign_work_days('2026-03-01','2026-03-06',i)) THEN 'PASS' ELSE 'FAIL' END);
 fp2:=public.correct_foreign_work_period(fp,jsonb_build_object('notes','TEST-FW corrected presence note'),'TEST-FW explicit correction');
 results:=results||jsonb_build_object('id','I03','status',CASE WHEN EXISTS(SELECT 1 FROM public.foreign_work_periods WHERE id=fp2 AND corrects_id=fp) AND EXISTS(SELECT 1 FROM public.audit_log WHERE entity_id=fp::text AND new_values->>'verification_status'='VOIDED') THEN 'PASS' ELSE 'FAIL' END);
 INSERT INTO public.time_entries(project_id,installer_id,entry_date,hours,travel_hours,source,client_id,note) VALUES(p,i,'2026-03-07',0,2,'manual',c,'TEST-FW travel only');
 results:=results||jsonb_build_object('id','E02','status',CASE WHEN NOT EXISTS(SELECT 1 FROM public.foreign_work_days('2026-03-07','2026-03-07',i) WHERE is_work) THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','E03','status',CASE WHEN NOT EXISTS(SELECT 1 FROM public.foreign_work_days('2026-03-07','2026-03-07',i) WHERE is_presence) THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','F02','status',CASE WHEN NOT EXISTS(SELECT 1 FROM public.foreign_work_days('2026-03-07','2026-03-07',i) WHERE is_work) THEN 'PASS' ELSE 'FAIL' END);
 INSERT INTO public.time_entries(installer_id,entry_date,hours,source,client_id,note) VALUES(i,'2026-03-08',1,'manual',c,'TEST-FW projectless');
 results:=results||jsonb_build_object('id','F01','status',CASE WHEN EXISTS(SELECT 1 FROM public.foreign_work_days('2026-03-08','2026-03-08',i) WHERE country='UNKNOWN' AND verification='INSUFFICIENT_DATA') THEN 'PASS' ELSE 'FAIL' END);
 INSERT INTO public.projects(name,ref,client_id,project_type,status,country,country_provenance,sandbox) VALUES('TEST-FW-CANCELLED','TEST-FW-CANCELLED-'||gen_random_uuid(),c,'installation','cancelled','Finland','CONFIRMED',true) RETURNING id INTO p2;
 INSERT INTO public.time_entries(project_id,installer_id,entry_date,hours,source,client_id,note) VALUES(p2,i,'2026-03-09',1,'manual',c,'TEST-FW cancelled time');
 results:=results||jsonb_build_object('id','A04','status',CASE WHEN NOT EXISTS(SELECT 1 FROM public.foreign_work_days('2026-03-09','2026-03-09',i) WHERE verification='VERIFIED') THEN 'PASS' ELSE 'FAIL' END);
 UPDATE public.projects SET country='unresolved country',country_code=NULL,country_provenance='UNKNOWN' WHERE id=p2;
 results:=results||jsonb_build_object('id','F03','status',CASE WHEN EXISTS(SELECT 1 FROM public.foreign_work_days('2026-03-09','2026-03-09',i) WHERE country='UNKNOWN' AND verification='INSUFFICIENT_DATA') THEN 'PASS' ELSE 'FAIL' END);
 UPDATE public.projects SET country='Sverige',country_provenance='DEFAULTED' WHERE id=p2;
 results:=results||jsonb_build_object('id','D03','status',CASE WHEN EXISTS(SELECT 1 FROM public.foreign_work_days('2026-03-09','2026-03-09',i) WHERE country='UNKNOWN' AND verification='INSUFFICIENT_DATA') THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','D05','status',CASE WHEN NOT EXISTS(SELECT 1 FROM public.foreign_work_days('2026-03-09','2026-03-09',i) WHERE country='SE' AND verification='VERIFIED') THEN 'PASS' ELSE 'FAIL' END);
 UPDATE public.projects SET country='Norge',country_provenance='DERIVED' WHERE id=p2;
 results:=results||jsonb_build_object('id','D02','status',CASE WHEN EXISTS(SELECT 1 FROM public.foreign_work_days('2026-03-09','2026-03-09',i) WHERE country='NO' AND verification='DERIVED') THEN 'PASS' ELSE 'FAIL' END);
 INSERT INTO public.foreign_work_rules(name,countries,metric,window_type,watch_threshold,review_threshold,critical_threshold,explanation,internal_note) VALUES('TEST-FW-RULE',ARRAY['FI'],'WORK_DAYS','CALENDAR_YEAR',3,5,8,'TEST-FW public','TEST-FW internal') RETURNING id INTO r;
 UPDATE public.foreign_work_rules SET watch_threshold=4 WHERE id=r;
 results:=results||jsonb_build_object('id','I04','status',CASE WHEN EXISTS(SELECT 1 FROM public.audit_log WHERE entity_id=r::text AND old_values->>'watch_threshold'='3' AND new_values->>'watch_threshold'='4') THEN 'PASS' ELSE 'FAIL' END);
 INSERT INTO public.foreign_work_documents(installer_id,doc_type,countries,status,valid_from,valid_to,notes) VALUES(i,'A1',ARRAY['FI'],'NOT_VERIFIED','2026-01-01','2026-12-31','TEST-FW doc') RETURNING id INTO doc;
 UPDATE public.foreign_work_documents SET status='VALID',notes='TEST-FW corrected note' WHERE id=doc;
 results:=results||jsonb_build_object('id','I05','status',CASE WHEN EXISTS(SELECT 1 FROM public.audit_log WHERE entity_id=doc::text AND new_values->>'status'='VALID' AND new_values->>'notes'='TEST-FW corrected note') THEN 'PASS' ELSE 'FAIL' END);
 results:=results||jsonb_build_object('id','L06','status',CASE WHEN NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.foreign_work_my_documents(i)) x WHERE x ? 'url' OR x ? 'storage_path' OR x ? 'document_id') THEN 'PASS' ELSE 'FAIL' END);
 PERFORM public.log_foreign_work_export(jsonb_build_object('test','TEST-FW-ROLLBACK'));
 results:=results||jsonb_build_object('id','I06','status',CASE WHEN EXISTS(SELECT 1 FROM public.audit_log WHERE actor_id=uid AND entity_type='foreign_work_export' AND new_values->>'test'='TEST-FW-ROLLBACK') THEN 'PASS' ELSE 'FAIL' END);
 RAISE EXCEPTION 'ROLLBACK_TEST_FIXTURES' USING ERRCODE='ZX001';
 EXCEPTION WHEN SQLSTATE 'ZX001' THEN NULL; WHEN OTHERS THEN results:=results||jsonb_build_object('id','FIXTURE_EXECUTION','status','FAIL','detail',SQLERRM); END;
 RETURN results;
END $$;
REVOKE ALL ON FUNCTION public.foreign_work_verify_rollback() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.foreign_work_verify_rollback() TO authenticated;